package dev.mariscore.placeholder;
import dev.mariscore.MarisCorePlugin;import dev.mariscore.storage.Storage;import dev.mariscore.util.Money;import me.clip.placeholderapi.expansion.PlaceholderExpansion;import org.bukkit.OfflinePlayer;import org.jetbrains.annotations.*;import java.math.BigDecimal;
public final class ShardsPlaceholders extends PlaceholderExpansion{private final MarisCorePlugin p;private final Storage s;public ShardsPlaceholders(MarisCorePlugin p,Storage s){this.p=p;this.s=s;} public @NotNull String getIdentifier(){return "shards";} public @NotNull String getAuthor(){return "Maris";} public @NotNull String getVersion(){return p.getDescription().getVersion();} public boolean persist(){return true;} public String onRequest(OfflinePlayer player,@NotNull String params){if(player==null||!p.isEnabled())return "0"; BigDecimal v=s.balanceCached(player.getUniqueId(),"shards"); return switch(params.toLowerCase()){case "value_formatted"->Money.fmt(v);case "value"->v.toPlainString();default->null;};}}
